   "slug": "art-history",
   "discipline": "Level 2 Art History internals are judged by overall judgement on whether the student understands the intent of the standard: the quality and scope of the evidence, descriptive or explanatory language, art-specific terminology, and the detail and precision of supporting evidence drawn from named art works (and other sources where required). Grades move from describing to explaining to evaluating; biographical or extra background not tied to the standard's focus, length and essay style are never the criterion.",
   "parallelHint": "different art works, artist, movement, medium or site (e.g. a different public sculpture, wharenui or painting)",
