     "code": "91183",
     "ref": "2.4",
     "credits": 4,
     "version": "Version 2 (published 20 November 2014)",
     "verified": "2026-10-25",
     "title": "Examine how media are used to create effects in art works",
     "criteria": {
      "achieved": "Examine how media are used to create effects in art works.",
      "merit": "Examine in-depth how media are used to create effects in art works.",
      "excellence": "Examine perceptively how media are used to create effects in art works."
     },
     "notes": [
      "EN2 — Examine involves: describing how media are used, applied and/or manipulated; describing the specific effects created by the use of media, using supporting evidence from art works.",
      "EN2 — Examine in-depth involves: explaining how media are used, applied and/or manipulated to create specific effects, using supporting evidence from art works.",
      "EN2 — Examine perceptively involves: evaluating how and why media are used, applied and/or manipulated to create specific effects, using supporting evidence from art works.",
      "EN3 — Art works may include but are not limited to: paintings, drawings, sculptures, installations, prints, collages, architecture, handcrafted objects, film, animation, photographs, digital images, whakaairo, kōwhaiwhai, tukutuku, tapa cloth.",
      "EN4 — Media refers to the materials and/or medium and/or technical means used to create art works (e.g. graphite, oil, watercolour, acrylic, ink, pastel, marble, bronze, wood, fibreglass, plastic, film, video, digital images, performance).",
      "EN5 — Effects refers to the results of an artist using selected media in a particular way, e.g. expressive, visual, texture, movement and scale effects, and effects on the viewer's thoughts, emotions and/or senses brought about by the media and/or processes used."
     ],
     "clarifications": {
      "date": "Updated May 2015",
      "points": [
       "Media can include the material worked or applied, the base it is applied to, and digital media.",
       "Effects are the visible results of using or applying media (texture, brushwork, lustre, colour) and may show in style, subject matter and meaning. Students must keep the focus on media and their effects, not other aspects of the work.",
       "'Specific' means precise: students find and describe or explain precise details of the effects in the art works.",
       "Achieved typically: simple descriptions of how at least TWO media are used, applied and/or manipulated, and of the specific effects, drawn from at least TWO art works.",
       "Merit typically: longer explanations of how at least two media create specific effects, supported by evidence from at least two art works; High Merit could emphasise the artist's intent.",
       "Excellence typically: complex, detailed evaluation of the artists' reasons for using, applying and/or manipulating media to create specific effects, supported by evidence from art works.",
       "All Art History standards: judgements rest on evidence relevant to the standard, not biographical or extra detail, and not length or essay style."
      ]
     },
