     "title": "Communicate understanding of an art history topic",
     "criteria": {
      "achieved": "Communicate understanding of an art history topic.",
      "merit": "Communicate in-depth understanding of an art history topic.",
      "excellence": "Communicate perceptive understanding of an art history topic."
     },
     "notes": [
      "EN2 — Communicate understanding involves: selecting and processing relevant information; describing key ideas using supporting evidence gathered from art works and other sources; drawing conclusions based on the information gathered.",
      "EN2 — Communicate in-depth understanding involves: explaining key ideas using supporting evidence gathered from art works and other sources; drawing reasoned conclusions based on the information gathered.",
      "EN2 — Communicate perceptive understanding involves: evaluating key ideas to draw insightful conclusions based on the information gathered, and using supporting evidence gathered from art works and other sources.",
      "EN3 — Art history topic refers to an area of inquiry selected by the teacher or the student, e.g. an art concept, issue or theme, an art movement, a selected artist, a period in art history.",
      "EN4 — Art works may include but are not limited to: paintings, drawings, sculptures, installations, prints, collages, architecture, handcrafted objects, film, animation, photographs, digital images, whakaairo, kōwhaiwhai, tukutuku, tapa cloth."
     ],
     "clarifications": {
      "date": "Updated May 2015",
      "points": [
       "The topic must relate to art history.",
       "At Achieved, 'conclusions' can be a single conclusion containing more than one point; at Merit and Excellence evidence should outline the results of the project and make judgements about the overall topic.",
       "Judgements are based on the criteria and Explanatory Notes only — NOT on research, planning, or the number or type of sources. Annotations and bibliographies may be required by the task but cannot be used to determine grades.",
       "Teachers may supply resources, provided students can still select and process information themselves.",
       "Essays or formal presentations are not required; notes or annotated images are acceptable at a level 7 standard.",
       "Achieved typically: describes at least TWO key ideas, supported by more than one art work and more than one other source; a specific topic helps.",
       "Merit typically: explains at least two key ideas with evidence from more than one art work and other source; reasoned conclusions are justified by clearly explained reasons.",
       "Excellence: evaluates several key ideas; insightful conclusions show an acute understanding of the topic."
      ]
     },
