     "title": "Communicate a considered personal response to art works",
     "criteria": {
      "achieved": "Communicate a considered personal response to art works.",
      "merit": "Communicate a convincing personal response to art works.",
      "excellence": "Communicate a perceptive personal response to art works."
     },
     "notes": [
      "EN2 — Communicate a considered personal response involves: expressing ideas, views, opinions, information and/or interpretations of the features of art works; using evidence from art works and/or other sources to support considered personal responses to the art works.",
      "EN2 — Communicate a convincing personal response involves: using evidence from art works and/or other sources to support reasoned personal responses to the art works.",
      "EN2 — Communicate a perceptive personal response involves: using evidence from art works and/or other sources to support evaluative personal responses to the art works.",
      "EN3 — Communicating may involve an oral response (e.g. a television talk-show, radio interview, gallery floor talk, a report to the class) or a written response (e.g. a critical review, interview questions and responses, an article for an art magazine, a letter, journal notes, a web page, a blog).",
      "EN4 — Art works may include but are not limited to: paintings, drawings, sculptures, installations, prints, collages, architecture, handcrafted objects, film, animation, photographs, digital images, whakaairo, kōwhaiwhai, tukutuku, tapa cloth."
     ],
     "clarifications": {
      "date": "Updated May 2015",
      "points": [
       "'Personal' means the student's own response to actual art works, not information from secondary sources. 'Considered' means given careful or deliberate thought.",
       "The standard concerns responses to ACTUAL art works: students should examine the real works rather than reproductions (photographs, online images).",
       "Decisions must be based on original evidence in the student's own words, not information from teachers, artists or texts. Other sources may support but are not required, and the number of sources must not affect the decision.",
       "Achieved typically: carefully worded statements in the student's own words expressing ideas, views, opinions and/or interpretations of the features of at least TWO art works, supported by evidence.",
       "Merit typically: clear explanations of at least two works in the student's own words, supported by explained points.",
       "Excellence typically: discusses and weighs up various points about at least two works and expresses personal conclusions, supported by evidence."
      ]
     },
