     "verified": "2026-10-25",
     "title": "Demonstrate understanding of art works in relation to their physical environments",
     "criteria": {
      "achieved": "Demonstrate understanding of art works in relation to their physical environments.",
      "merit": "Demonstrate in-depth understanding of art works in relation to their physical environments.",
      "excellence": "Demonstrate critical understanding of art works in relation to their physical environments."
     },
     "notes": [
      "EN2 — Demonstrate understanding involves: demonstrating links between the art works and the environmental contexts in which they are seen, such as the characteristics of the physical surroundings in the immediate vicinity, the contemporary or historical features of the environment, the physical conditions in which the art works exist, the purposes for which the art works were made and presented, the influences which contributed to the features of the art works; and describing the features of art works and their physical environments.",
      "EN2 — Demonstrate in-depth understanding involves: explaining the relationships between art works and their physical environment by referring to their environmental contexts and/or purposes and/or influences.",
      "EN2 — Demonstrate critical understanding involves: evaluating the relationships between art works and their physical environments.",
      "EN3 — Art works may include but are not limited to: paintings, drawings, sculptures, installations, prints, collages, architecture, handcrafted objects, film, animation, photographs, digital images; whakaairo, kōwhaiwhai, tukutuku, tapa cloth.",
      "EN4 — Physical environments refer to the places in which art works exist, within or outside the student's own locality, e.g. public, private or corporate spaces and buildings such as parks, streets, marae, churches, town halls."
     ],
     "clarifications": {
      "date": "Updated May 2015",
      "points": [
       "Physical environments are the sites where works are located (public space, gallery, any place works may be seen); may include a digital environment or a book if it has a specific relationship to the work.",
       "The standard lets students visit and examine actual works in their local environment; teachers must choose works with enough scope to explore the relationships fully.",
       "Students need not address every feature in EN2, and decisions must not be based on how many features are described, explained or evaluated.",
       "Decisions rest on demonstrated understanding of the RELATIONSHIPS between works and environments; unlinked descriptions of either the works or the environments are not enough.",
       "Achieved typically: statements or annotations describing features of at least TWO works and their environments, identifying connections.",
       "Merit typically: explanations of relationships between at least two works and their environments, referring to purposes and/or influences.",
       "Excellence typically: evaluation of relationships, with conclusions showing critical understanding."
      ]
     },
