   "discipline": "Level 2 Biology internals are judged on the quality of biological thinking at curriculum level 7: accurate biological ideas used to describe (Achieved), to give reasons how or why (Merit), and to link several ideas through comparing, justifying or evaluating (Excellence). In investigations the chain from hypothesis to processed data to conclusion must hold together. Length, presentation and the number of facts are never criteria in themselves; a grade moves when the explanation does.",
