     "title": "Investigate the application of motivation theory in a business",
     "criteria": {
      "achieved": "Investigate the application of motivation theory in a business.",
      "merit": "Investigate in-depth the application of motivation theory in a business.",
      "excellence": "Comprehensively investigate the application of motivation theory in a business."
     },
     "notes": [
      "EN3 — Investigate typically involves: collecting evidence relevant to the motivation practice(s) in a business; stating results of the investigation supported by relevant examples; explaining the relationship between the motivation practice and motivation theory; stating a Māori business concept(s) where relevant to the motivation theory.",
      "EN4 — Investigate in depth typically involves: collecting in-depth evidence about the motivation practice(s) in a business; explaining results of the investigation supported by relevant examples; fully explaining the relationship between the motivation practice and motivation theory; including a Māori business concept(s) where relevant to the motivation theory to support explanations.",
      "EN5 — Comprehensively investigate typically involves: collecting in-depth evidence about the motivation practice(s) in a business from a range of sources; fully explaining the results of the investigation supported by relevant examples; justifying the link between the motivation theory and the motivation practice; integrating a Māori business concept(s) where relevant to the motivation theory to fully support explanations.",
      "EN6 — Motivation theory refers to the theories defined under the content and concepts in the Teaching and Learning Guide; motivation practice refers to the business practice(s) used to motivate staff; application of motivation theory refers to candidate analysis of the relationship between the motivation practice(s) and theory."
     ],
     "clarifications": {
      "date": "November 2016",
      "points": [
       "Students investigate how employees are motivated in ONE specific business, by meeting owners, HR managers or employees; for Excellence a range of sources is required.",
       "Practices to look at include whether the business measures and rewards performance, offers flexible working, invests in training, and similar.",
       "Students describe the practices found, then explain how or why they relate to the theories studied. The practices discussed must be the ones investigated.",
       "Other theorists, including contemporary ones, can be used if relevant to the practices in the chosen business.",
       "Discussing motivation theory alone is not evidence of application — watch for ‘data dumps’ of theory instead of explanations of relevant examples. The depth of analysis of the practice–theory relationship determines the grade.",
       "Achieved: states the relationship and offers proof of it. Merit: more in-depth proof, explaining how or why practices occur from the business’s perspective. Excellence: justifies the link by explaining how and why practices occur and their relevance in context, and justifies practices and theory in terms of achieving business goals (e.g. non-financial rewards matter more in a state school where salaries are set nationally)."
      ]
     },
