   "discipline": "Level 2 Chemistry internals are judged on the chemistry itself: correct species, formulae, balanced equations and calculations, linked explicitly to the student's own observations, data or the technology in question, using chemistry vocabulary, symbols and conventions. In the practical standards the grade rests on what the student planned, measured, calculated and explained from their own primary data; in the report standards it rests on processed understanding, not on the amount of researched description. Length, presentation and generic lab-safety statements are never criteria in themselves.",
   "parallelHint": "a different consumer product, analyte or titration type (e.g. vitamin C in a juice instead of ethanoic acid in vinegar), a different set of ions or functional groups, a different redox pair, or a different current technology",
