     "title": "Carry out a practical investigation into a substance present in a consumer product using quantitative analysis",
     "criteria": {
      "achieved": "Carry out a practical investigation into a substance present in a consumer product using quantitative analysis.",
      "merit": "Carry out an in-depth practical investigation into a substance present in a consumer product using quantitative analysis.",
      "excellence": "Carry out a comprehensive practical investigation into a substance present in a consumer product using quantitative analysis."
     },
     "notes": [
      "EN2 — Carry out a practical investigation (Achieved) involves: developing a workable plan to determine if the consumer product sample and/or titration procedure requires modification; collecting, recording and processing a sufficient quantity of data to enable a conclusion to be reached; determining the concentration of a substance relevant to the investigation; describing how significant variables were controlled in the investigation.",
      "EN2 — Carry out an in-depth practical investigation (Merit) involves: using results from preliminary trials to develop a valid plan to modify the consumer product sample and/or titration procedure; collecting, recording and processing quality data that enables a valid conclusion to be reached; accurately determining the concentration of the standard solution; and the substance present; explaining how control of variables improved the quality of the investigation.",
      "EN2 — Carry out a comprehensive practical investigation (Excellence) involves: accurately determining the concentration of the substance in the consumer product, including correct use of significant figures and units; justifying how modifying the consumer product sample and/or the titration procedure improved the validity and accuracy of the investigation; evaluating the outcome of the investigation in relation to the consumer product.",
      "EN3 — A practical investigation involves planning, carrying out the investigation, collecting primary data, processing and interpreting the data, and reporting. The initial method may be modified as the investigation proceeds.",
      "EN4 — Quantitative analysis means using a titration to determine the concentration of a substance in a sample.",
      "EN5 — The titration is limited to acid-base, complexometric, precipitation or oxidation-reduction.",
      "EN6 — Determining concentration requires the use of stoichiometric principles and the relationships n = m/M and c = n/V."
     ],
     "clarifications": {
      "date": "December 2021 (updated to address issues arising from moderation)",
      "points": [
       "The standard covers planning an investigation into a substance in a consumer product, collecting primary data, processing and interpreting it, and reporting on the investigation.",
       "Learners must be given an outline of the titration procedure that leaves room for them to modify aspects of it (a fully prescribed method removes the planning evidence).",
       "Determining concentration requires evidence of stoichiometric principles and of n = m/M and n = cV. Stoichiometric principles involve mole ratios, and the task must include at least one calculation that uses a stoichiometric ratio that is not one-to-one.",
       "Achieved: develop a plan to decide whether the sample and/or procedure needs modifying; collect, record and process data, calculate the relevant concentration and reach a conclusion; describe how significant variables (those that could substantially affect results) were controlled.",
       "Merit: use trial results to develop a valid plan to modify the sample and/or procedure; collect quality data, accurately determining the concentration of the standard solution and of the substance in the product, and reach a valid conclusion; explain how controlling variables improved the quality of the investigation.",
       "Excellence: accurately determine the concentration of the substance in the consumer product with relevant significant figures and units; justify, with examples specific to this investigation, how the modifications improved both validity and accuracy; evaluate the conclusion in relation to the consumer product."
      ]
     },
