      "EN2 — Carry out an in-depth investigation (Merit) involves: explaining the identification of chemical species present by linking the primary data to the procedure; writing relevant equations to explain all the changes occurring during the identification procedure; explaining the significance of an identified chemical species for people and/or the environment.",
      "EN2 — Carry out a comprehensive investigation (Excellence) involves: justifying the identification of chemical species present by linking secondary data and chemical principles to the reactions occurring during the analysis; discussing the significance of an identified chemical species for people and/or the environment.",
      "EN3 — Identification procedures may include: identifying ions based on solubility rules and the formation of complex ions; identifying organic compounds based on functional group reactions.",
      "EN4 — Secondary data may include: solubility rules and formulae of complex ions; a functional group reaction map; relevant scientific literature."
