       "Choose events with sufficient and accessible primary source evidence. The event must come from the ancient Greek or Roman world; Egyptian, Hebrew or Babylonian events, or events discussed from a Biblical perspective, are unsuitable.",
       "The event must be historical, not mythological or literary. For the Trojan War, relying only on the Iliad and Odyssey may limit depth and perceptiveness; archaeological and artistic evidence makes meeting the standard more secure.",
