       "The relationship must be between a classical civilisation and a POST-classical one. Some students attempt to relate Greece and Rome to contemporary ancient cultures (such as Egyptian or Babylonian); they should instead consider cultures that post-date the Roman period.",
       "Contexts need sufficient, accessible primary source evidence. Teachers may supply relevant primary sources.",
       "For Merit and Excellence, primary sources must be specifically relevant and enhance the explanation of the relationship; direct or indirect quotations and specific references to artworks or architecture are useful.",
