     "watch": [
      "The outcome decided at the start (e.g. 'I will make an app') with research gathered only to justify it, or a task that fixes the outcome type.",
      "Research copied or pasted with no organisation or analysis, or a summary that does not connect back to the inquiry questions.",
      "A proposal too vague to build from — no end users, scope, requirements or resources.",
      "Milestones shown only as a plan with no evidence of being met or of variations explained; or a project board that appears reconstructed after the fact.",
      "Implications named in a list (privacy, accessibility, ethics) but not analysed in relation to this proposal.",
      "Perspectives or end-user survey data that look invented or generic (AI-generated personas, round-number results with no raw data); statistics and URLs that need checking — mark as 'check', never as 'fabricated'.",
      "Linked evidence (Trello, Google Docs) that the moderator will not be able to open."
     ],
