   "slug": "drama",
   "discipline": "Level 2 Drama 2.5 is judged on how well the student examines a playwright's concerns and where and how they are expressed across extracts from at least two of that playwright's texts — moving from identifying concerns and where they appear (Achieved), to detailed explanation with examples from the texts (Merit), to insightful connections between the plays and the wider world of the play and playwright (Excellence). Performance or acting quality is never the criterion; dramatic formats (in-role presentation, hot seating, workshop) are only the vehicle for the evidence.",
   "parallelHint": "a different playwright (or two different plays by the same playwright) with a different socio-historical world, so students cannot copy the concerns, quotations or context",
