     "code": "91189",
     "ref": "2.3",
     "credits": 4,
     "version": "Version 2 (published 20 November 2014)",
     "verified": "2026-10-25",
     "title": "Investigate geological processes in a New Zealand locality",
     "criteria": {
      "achieved": "Investigate geological processes in a New Zealand locality.",
      "merit": "Investigate in depth geological processes in a New Zealand locality.",
      "excellence": "Investigate comprehensively geological processes in a New Zealand locality."
     },
     "notes": [
      "EN2 — Investigate (Achieved) involves: identifying the types of rock(s) found in the locality; describing the plate tectonic and rock cycle processes that have formed the types of rocks in the locality; describing the erosional processes that have shaped the current landforms in the locality.",
      "EN2 — Investigate in depth (Merit) is further developed by: EXPLAINING the plate tectonic and rock cycle processes that have formed the types of rocks in the locality; EXPLAINING the erosional processes that have shaped the current landforms in the locality.",
      "EN2 — Investigate comprehensively (Excellence) is further developed by: DISCUSSING THE LINK between the plate tectonic processes and the rock cycle processes that have formed the types of rocks in the locality; DISCUSSING THE LINK between the erosional processes and the shape of the current landforms in the locality.",
      "EN3 — A New Zealand locality is considered to be anywhere within the Zealandia continent.",
      "EN4 — Geological processes will include plate tectonics and the rock cycle, and erosion.",
      "EN5 — Conditions of Assessment are published by the Ministry of Education (NCEA on TKI)."
     ],
     "clarifications": {
      "date": "Updated May 2015",
      "points": [
       "To reach Achieved students identify the types of rock in the locality, describe the plate tectonic and rock cycle processes that formed them, and describe the erosional processes that shaped the current landforms.",
       "The locality can be anywhere in New Zealand, the Cook Islands or Niue.",
       "The processes described must match current geological understanding of the chosen locality. A general account of rock formation is not enough — e.g. a general explanation of how marble forms would not sufficiently explain the Takaka marble.",
       "Specific rock names (e.g. rhyolite) are not required, though they can help show how plate tectonics relates to the rock cycle; what is required is the correct rock TYPE (e.g. igneous).",
       "Students carry out an investigation to collect primary and/or secondary evidence and use their findings to describe the geological processes; a field trip may be part of it but is not mandatory.",
       "The critical component is reporting on the geological processes in the locality and showing how they contribute to that locality's geology.",
       "Teachers may provide information, research, experiments, videos and similar resources (primary and/or secondary)."
      ]
     },
     "nmr": [],
