   "discipline": "Level 2 English internals are judged at curriculum level 7. In the reading and viewing standards the grade rests on the quality of the student’s interpretation — developed (Achieved), reasoned and clear or convincing (Merit), insightful and/or original or perceptive (Excellence) — and every claim must be tied to specific, relevant detail from the texts. In the writing standard the grade rests on how ideas are developed, sustained and structured and how deliberately language is crafted for effect. Plot summary, background information and length never earn credit in themselves.",
