     "title": "Use information literacy skills to form developed conclusion(s)",
     "criteria": {
      "achieved": "Use information literacy skills to form developed conclusion(s).",
      "merit": "Use information literacy skills to form developed conclusion(s) convincingly.",
      "excellence": "Use information literacy skills to form developed conclusion(s) perceptively."
     },
     "notes": [
      "EN2 — Use information literacy skills involves completing a systematic exploration into a valid area of inquiry in order to form conclusion(s). The steps taken include: framing the inquiry within an authentic, relevant context based on carefully considered information needs (identifying an area or direction for investigation, or posing a question(s)); selecting and using appropriate strategies for locating and processing information; evaluating the reliability and usefulness of selected information in relation to the inquiry.",
      "EN2 — Form developed conclusion(s) involves creating and building conclusion(s) that are connected to the purpose of the inquiry and based on information gathered in the inquiry. This includes expressing an opinion or judgement, reaching a decision, or suggesting a solution.",
      "EN2 — Convincingly involves formulating conclusion(s) that are reasoned and clear. Perceptively involves formulating conclusion(s) that are insightful and/or original.",
      "EN3 — Information must be from written, oral and/or visual texts selected by the student.",
      "EN4 — The information literacy skills and the presentation of conclusions must be within the English learning area."
     ],
     "clarifications": {
      "date": "Updated May 2015 (updated in its entirety from moderation)",
      "points": [
       "The inquiry arises from text studies in English (e.g. literature or independent reading) and is framed in a real-world, authentic context. Fiction can raise an issue (e.g. penal reform), but the investigation and sources must lie outside the fictional world.",
       "Sources are generally non-fiction (primary and secondary sources, differing viewpoints, articles). Fiction, advertisements and biography may support other sources but cannot form the basis of a systematic inquiry. The standard does not assess literary analysis.",
       "Topics should go beyond collecting and presenting information; open questions are more likely to lead to conclusions that show understanding.",
       "Students choose their own sources and must document the selection and processing (highlighting, annotations, data charts, notes). All selected information must be referenced. Evaluation of reliability and usefulness must appear in the notes or in the conclusions.",
       "Conclusions build ideas and knowledge from the gathered information and may be an opinion, judgement, question, challenge to current thinking or solution. They are more developed when they draw on differing sources and viewpoints, and must clearly link to the selected and processed information."
      ]
     },
