      "EN3 — Aspects are the nature of the issue, the viewpoints and how they change over time, and the evaluation of courses of action. A contemporary issue affects people or places now or in the near future. A geographic issue is a topic, concern, problem, debate or controversy linked to a natural or cultural environment that has a spatial dimension. The issue must be a local or national issue within New Zealand."
