     "notes": [
      "EN2 — Achieved involves: describing a global pattern of the geographic topic, using geographic terminology; explaining the factors and/or processes that contribute to the pattern; explaining the significance of the topic for people.",
      "EN2 — In depth (Merit) involves: describing, in detail, the global pattern of the geographic topic, using geographic terminology; explaining, in detail, the factors and/or processes that contribute to the pattern; explaining, in detail, the significance of the topic for people.",
      "EN2 — Comprehensively (Excellence) involves: fully describing the global pattern of the geographic topic, using geographic terminology; fully explaining the factors and/or processes that contribute to the pattern; fully explaining, showing insight, the significance of the topic for people.",
      "EN3 — A geographic topic is a natural and/or cultural study at a global scale. Its aspects are the global pattern, the factors and/or processes that contribute to it, and its significance for people’s lives in different parts of the world.",
      "EN4 — A global pattern is a fixed spatial or temporal arrangement of a phenomenon across different continents or hemispheres.",
      "EN5 — Factors are the circumstances that contribute to a global pattern; processes are the sequences of events that contribute to it.",
      "EN6 — Significance is the importance of a topic for people in relation to a specific phenomenon; it may be social, economic, environmental, political or cultural (e.g. place-based identity, environmental sustainability, economic development)."
     ],
     "clarifications": {
      "date": "June 2025 (updated for Version 4)",
      "points": [
       "The global spatial dimension is now explicit: ‘a spatial or temporal pattern’ became ‘a global pattern’. References to concepts at Merit and Excellence were removed.",
       "The Conditions of Assessment guide teacher input on topic selection and resources. Resources should strongly feature evidence that fully describes a global spatial or temporal pattern (world maps, statistics).",
       "The topic must be clearly geographic and relate to the ‘Place and Environment’ strand; sociological topics not linked to place may pull students away from geographic approach and terminology. Evidence of the global spatial dimension must be explicit throughout.",
       "Spatial patterns are most common at this level. Asking students to draw their own maps often produces no discernible pattern, making the global pattern harder to explain.",
       "Explanation of factors and/or processes must stay focused on the identified global pattern; explicit links between factors/processes and the pattern are required to show the causal relationship."
      ]
     },
