     "title": "Apply spatial analysis, with guidance, to solve a geographic problem",
     "criteria": {
      "achieved": "Apply spatial analysis, with guidance, to solve a geographic problem.",
      "merit": "Effectively apply spatial analysis, with guidance, to solve a geographic problem.",
      "excellence": "Comprehensively apply spatial analysis, with guidance, to solve a geographic problem."
     },
     "notes": [
      "EN2 — Achieved involves: collecting spatial data relevant to the geographic problem; completing manipulations of the spatial data to produce a layout related to the problem; explaining an appropriate solution, based on the manipulations, that is supported by evidence.",
      "EN2 — Effectively (Merit) involves: collecting sufficient spatial data to address the geographic problem; completing manipulations of the spatial data to produce an accurate layout related to the problem; explaining, in detail, an appropriate solution, based on the manipulations, that is supported by evidence.",
      "EN2 — Comprehensively (Excellence) involves: fully explaining a valid solution, based on the manipulations, that is supported by detailed evidence.",
      "EN3 — With guidance refers to the degree of teacher guidance on the type and selection of data and the geospatial technique used. A geographic problem concerns the natural and/or cultural environment at a given location and has a spatial dimension; it cannot be a simulation. Collecting spatial data means collecting data with a spatial component in the field or accessing spatial data from other sources. A layout is a map, which may also include tables, graphs and images.",
      "EN3 — Manipulations are data transformations, including measuring, layering, changing the symbols used, sorting and editing a table, querying the map, using coordinate systems, and displaying a graph based on the map. Spatial analysis involves collecting, manipulating and presenting spatial data. Geospatial techniques should be used to manipulate and present spatial data in ways that support problem solving; students may use appropriate technology."
     ],
     "clarifications": {
      "date": "May 2015 (updated to address issues from moderation)",
      "points": [
       "The geographic problem must have a spatial dimension. It can be hypothetical but must be based on genuine, real data. Phrasing it as a question helps, and a local setting has worked best.",
       "The Conditions of Assessment set out teacher input on topic selection, resources and geospatial technologies.",
       "Teachers provide resources, but students choose what data they need and how much. Sufficiency is about selecting the most relevant data, not quantity.",
       "Layout accuracy depends on applying appropriate geographic conventions and on the precision of the manipulations. Several manipulations may be combined for more accurate and effective results, logically planned to support problem solving.",
       "After an image is cropped or manipulated, its orientation, scale and key may need to be changed or added.",
       "The proposed solution must be based on the manipulations and explained using supporting evidence from the layout.",
       "For Achieved and Merit an appropriate solution means ‘what might work’; for Excellence a valid solution means ‘what should work’, showing deeper understanding of the environment and context."
      ]
     },
