   "slug": "health",
   "discipline": "Level 2 Health is judged on applying the underlying concepts (hauora, socio-ecological perspective, health promotion, attitudes and values) to a specific situation: factors are explained in terms of how and why they affect wellbeing, and strategies or actions are tied back to those factors at personal, interpersonal and societal levels. Depth comes from specific links to the situation and critical understanding, not from length, lists of factors, or retelling a story.",
   "parallelHint": "a different change situation, wellbeing issue or identity scenario, e.g. moving country instead of family separation, or a community nutrition action instead of an anti-bullying action",
   "privacyNote": "Student work in Health often includes personal disclosures (their own experiences of change, grief, whānau, relationships, gender and sexual identity, mental health). If anything in the work suggests a student may be unsafe or at risk (self-harm, abuse, violence, coercion, serious distress), the AI must say so to the teacher in a separate line at the very top of its response, before any grading, and must not grade around it or quote it back. Feedback should never ask a student to disclose more personal detail than the task requires.",
