     "code": "91236",
     "ref": "2.2",
     "credits": 5,
     "version": "Version 2 (published 20 November 2014)",
     "verified": "2026-10-25",
     "title": "Evaluate factors that influence people's ability to manage change",
     "criteria": {
      "achieved": "Evaluate factors that influence people's ability to manage change.",
      "merit": "Evaluate in depth, factors that influence people's ability to manage change.",
      "excellence": "Evaluate comprehensively, factors that influence people's ability to manage change."
     },
     "notes": [
      "EN2 — Evaluate (Achieved) involves: explaining risk and protective factors that contribute to people's ability to manage change situations; AND recommending a combination of personal, interpersonal and societal strategies to maintain the protective factors and/or minimise the risk factors.",
      "EN2 — Evaluate in depth (Merit) involves: explaining, in detail, risk and protective factors that are clearly linked to the change situations; AND recommending personal, interpersonal and societal strategies specific to the change situations.",
      "EN2 — Evaluate comprehensively (Excellence) involves providing an explanation that demonstrates critical understandings of the risk and protective factors influencing people's ability to manage change situations, and strategies for maintaining the protective factors and minimising the risk factors. Critical understandings will be shown, for example, through a relevant combination of: a conceptually sound understanding of resilience in relation to the change situation; insight beyond the immediate evidence (e.g. drawing on similar situations); understanding how a major life change results in many inter-related changes; linking risk and protective factors to the relevant determinants of health; explaining interrelationships between the personal, interpersonal and societal factors or the strategies for building resilience.",
      "EN3 — Risk and protective factors, and strategies for managing change, are related to the concept of resilience.",
      "EN4 — The context is a significant change situation related to the key learning area of mental health; a significant change results in numerous changes to be considered in the evaluation. Situations may include illness or disability, family separation or relationship break-up, changing house/school/country, significant loss and grief, drug use and misuse, significant failure, or repeated or ongoing pressured, risky or stressful life situations. Focusing on suicide or eating disorders is not appropriate."
     ],
     "clarifications": {
      "date": "December 2017",
      "points": [
       "Students respond to a scenario or interview someone who has experienced change. The situation must allow risk and protective factors to be identified at personal, interpersonal and societal levels. With an interview, the evaluation must address the standard's requirements, not retell the person's story.",
       "Risk and protective factors are personal, interpersonal and societal influences that exist BEFORE the change occurs. Risk factors make coping harder; protective factors make it easier.",
       "Students describe each factor and explain how and why it helps or hinders coping and resilience. Selected factors should relate to those in the Youth Development Strategy Aotearoa (2002).",
       "Strategies at personal, interpersonal and societal levels maintain protective factors or reduce risk factors; students describe the actions involved and justify how each helps the person cope with this change and build resilience for future changes.",
       "Merit: factors are clearly linked to the change situation and explained in depth; strategies are the key actions for managing the change, with detailed explanation of why and how they build resilience.",
       "Excellence: shows the factors and strategies are critical to the change situation and to building resilience now and in the future; may show that a major life change leads to many interrelated changes, link factors to health or resilience literature, or explain how factors and strategies interrelate."
      ]
     },
     "nmr": [
      "Grades were changed where the change situation was unclear or where students wrote about several; students need one specific, clearly stated change situation (see EN4).",
      "Risk and protective factors must exist before the change happens and must be identified at personal, interpersonal and societal levels.",
      "Strategies must be clearly tied to their level, framed around the individual, others and the wider community.",
      "Each strategy needs a clear description, the action involved, and reasons showing how it helps the person cope now and builds resilience for future change.",
      "Evaluations that only retell the story of change (especially from interviews) do not meet the standard."
     ],
