       "Students may act individually or in groups, and different groups may address the same issue. All submitted work must be the student's own; in group actions each student's log must record their own contributions.",
       "Achieved: identify a well-being issue; set a SMART goal and explain how achieving it enhances well-being; develop a workable plan of actions, each with barriers, enablers and projected timeframes; implement the plan and keep a log; evaluate effectiveness, linking to well-being.",
