   "discipline": "Level 2 mathematics standards are judged on the level of thinking shown in solving a problem: Achieved is selecting and using relevant level-7 methods with working and answers that say what they represent; Merit is relational thinking (connected steps, a model formed and used, findings linked to context); Excellence is extended abstract thinking (a strategy, generalisation or chain of reasoning) communicated with correct mathematical statements. Statistics standards are judged on the statistical enquiry cycle: each component present (Achieved), linked to the context with supporting evidence (Merit), and statistical and contextual knowledge integrated throughout (Excellence). Length, neatness and the number of calculations are never the criterion.",
