      "EN2 — With justification (Merit) involves linking components of the questionnaire design process to the context and explaining relevant decisions made in the design process.",
      "EN2 — With statistical insight (Excellence) involves integrating statistical and contextual knowledge relevant to the purpose of the survey throughout the design process.",
      "EN3 — The components of the questionnaire design process involve: clarifying the specific information needs of the survey and the groups who will use the data; posing survey questions, considering sources of variation by determining relevant variables, determining appropriate measures for each variable, using an appropriate range of question types; checking the survey questions by carrying out a desk review and conducting a pilot survey(s) including collecting and recording data; refining the questionnaire based on the results of the pilot survey; documenting the design process including the draft and final questionnaire.",
