      "points": [
       "Students can be given a purpose for their questionnaire. The context should be familiar, and background information about the survey's purpose and its users should be available.",
       "A desk review looks for likely problems and can be done by the designer, another student, or both. A desk review is needed after question changes, so the process will likely involve more than one.",
       "A pilot survey is a trial run with a small sample from the target population, including collecting and processing data, used to find problems and improve efficiency.",
       "Achieved: evidence of EACH component in EN3, with written documentation of the entire process.",
       "Merit: justification by explaining decisions, e.g. the choice and type of questions and changes made after the desk review and pilot survey.",
       "Excellence: statistical insight integrating statistical and contextual knowledge — reflecting on all aspects of the design process, researching the purpose of the questionnaire, and possibly refining the purpose to meet the information needs of the survey and its data users."
      ]
