     "notes": [
      "EN2 — Evaluate a statistically based report (Achieved) involves identifying and commenting on features and findings of a survey that are relevant to the report's purpose.",
      "EN2 — With justification (Merit) involves supporting the comments on the features and findings with reference to statistical evidence and the statistical processes used to carry out the survey.",
      "EN2 — With statistical insight (Excellence) involves integrating statistical and contextual information to assess the quality of the report in terms of its purpose.",
      "EN3 — Features of a survey include: population measures and variables; sampling methods; survey methods; sampling and possible non-sampling errors; sample size.",
      "EN1 — Related to the Level 7 objective: evaluate statistically based reports, identifying sampling and possible non-sampling errors in surveys, including polls."
     ],
     "clarifications": {
      "date": "July 2019 ('Statistically based report' section updated)",
      "points": [
       "Students evaluate a statistically based report and, where possible, have access to the actual survey results. The report should include significant statistical features so both features and findings can be discussed.",
       "The focus is on evaluating the report, not on students forming their own conclusions from the data. Teachers can give focus questions to structure the evaluation.",
       "Achieved: students identify and comment on survey features and findings relevant to the report's purpose; they need to understand that purpose and would usually identify it themselves.",
       "Students must identify and comment on BOTH the features of the report and its findings.",
       "Merit: the evaluation is justified with reference to statistical evidence and the processes used (e.g. survey method, choice of analysis).",
       "Excellence: statistical insight integrating statistical and contextual information — considering how aspects of the report affect the findings and how possible issues might be addressed."
      ]
     },
