      "EN2 — Relational thinking (Merit) involves one or more of: selecting and carrying out a logical sequence of steps; connecting different concepts or representations; demonstrating understanding of concepts and terms; forming and using a model; AND ALSO relating findings to a context, or communicating thinking using appropriate mathematical statements.",
      "EN2 — Extended abstract thinking (Excellence) involves one or more of: devising a strategy to investigate or solve a problem; identifying relevant concepts in context; developing a chain of logical reasoning, or proof; forming a generalisation; AND ALSO using correct mathematical statements, or communicating mathematical insight.",
