     "title": "Demonstrate understanding of narrative in media texts",
     "criteria": {
      "achieved": "Demonstrate understanding of narrative in media texts.",
      "merit": "Demonstrate in-depth understanding of narrative in media texts.",
      "excellence": "Demonstrate critical understanding of narrative in media texts."
     },
     "notes": [
      "EN2 — Demonstrate understanding involves describing how selected narrative features contribute to narrative in media texts.",
      "EN2 — Demonstrate in-depth understanding involves explaining how selected narrative features contribute to narrative in media texts.",
      "EN2 — Demonstrate critical understanding involves examining the implications of the contribution of selected narrative features to narrative in media texts.",
      "EN3 — Media texts include, but are not limited to, television and radio programmes, films, feature articles, web pages and music videos.",
      "EN4 — Narrative features that may be examined: mise en scène; visual elements; character; conflict or opposition; narrative perspective; symbols, motifs, or themes; sound; setting; manipulation of time; narrative structure."
     ],
     "clarifications": {
      "date": "Updated December 2020",
      "points": [
       "Students examine TWO media texts and show how TWO narrative features develop the narrative in each.",
       "For Achieved, students must go beyond describing a feature and discuss the contribution it makes to the overall narrative or story.",
       "Texts should be complex enough for curriculum level 7, with clear narrative conventions; texts that complement each other (structure, genre or context) can help.",
       "Discussion should focus on how a feature contributes to the overall narrative, not on technical close reading. Teachers may select the features; conflict, manipulation of time, character construction and setting are useful.",
       "The two features need not be the same in both texts, though using the same two across linked texts can help analysis.",
       "Excellence: 'examining the implications' means discussing the effect or impact of a feature on the narrative as a whole — e.g. character development, how the narrative arc is resolved, audience reaction, or how the feature shapes meaning, understanding or engagement.",
       "Sufficiency: two features in each of the two texts must be discussed, with enough evidence across the responses to award a holistic grade."
      ]
     },
