     "title": "Demonstrate understanding of representation in the media",
     "criteria": {
      "achieved": "Demonstrate understanding of representation in the media.",
      "merit": "Demonstrate in-depth understanding of representation in the media.",
      "excellence": "Demonstrate critical understanding of representation in the media."
     },
     "notes": [
      "EN2 — Demonstrate understanding involves describing the representation and its effect across media texts. This includes describing: what the representation is; how features of the representation are created by media texts; the effect of the media representation.",
      "EN2 — Demonstrate in-depth understanding involves providing reasoned explanations for the effect of the representation across media texts. This includes such aspects as: reasons for the difference between the representation and reality; reasons for stereotypes, messages, and/or values created by the representation; reasons why the selection and/or omission of material reinforce stereotypes, messages, and/or values.",
      "EN2 — Demonstrate critical understanding involves examining likely consequences of the representation and drawing conclusions based on the evidence across media texts. The examination includes aspects of the representation such as: the effectiveness of the features in creating the representation; implications of the difference(s) between the representation and reality; the implications and/or effectiveness of the stereotypes, messages, and/or values that are created by the representation; the implications and issues associated with the selection and/or omission of material.",
      "EN3 — Representation means the way a group, issue, idea, event, or place is represented in the media. A representation communicates messages and values that have social significance, reflecting world views, ideologies, societal assumptions and biases. It may be broad (e.g. children, the Olympics, New Zealand) or more specific (e.g. a topical issue, a local event, your school, women in film noir).",
      "EN4 — A reasoned explanation involves a logical argument supported by specific evidence."
     ],
     "clarifications": {
      "date": "Updated December 2017 (predates Version 4 of the standard)",
      "points": [
       "The standard focuses on how a media representation relates to society and/or its context; at Achieved the description and effects should be detailed enough for curriculum level 7.",
       "Students must clearly describe a representation of a group, issue, idea, place or event, the features that create it, and its effect. The representation may be given or chosen with teacher guidance; texts must allow discussion of those features.",
       "Avoid close readings of single texts: discuss the representation across the texts as a whole, and draw conclusions about the representation, not about each text.",
       "Discussion of effects and implications needs detailed, supported examples from at least THREE media texts, plus other sources — not only the student's own observations.",
       "For Merit and Excellence, students need to discuss only one or two of the aspects listed in EN2."
      ]
     },
