   "discipline": "Level 2 Music 2.9 is judged on the quality of the investigation into an aspect of New Zealand music: a chronological overview, a profile, the significant musical characteristics (normally including analysis of a representative song or work) and an evaluation of the aspect's significance in the New Zealand music scene, moving from enquiry (Achieved) to a thorough, informed investigation (Merit) to one that integrates implications, ideas and perspectives and interprets significant factors (Excellence). Presentation format and length are never the criterion.",
