       "Functional anatomy is part of understanding biomechanics and must be explained, not shown by naming joints or listing muscles.",
       "Achieved: what the principle is, how and why each principle relates to learning the skill, and specific examples from the student's own experience. For verbal responses the teacher's annotation should be summarised to reflect the criteria.",
