      "EN2 — Examine critically (Excellence) involves explaining the interrelationship between relevant sociological factors and the significance, by identifying assumptions, identifying who is advantaged and disadvantaged, considering pros and cons, and making judgements and providing supporting evidence.",
      "EN3 — Sociological factors and issues may include societal, political, economic, environmental, ethical, cultural and historical.",
      "EN4–5 — Others may include friends, family or whānau. Society may range from community and hapū to iwi, region, nation or global society.",
      "EN6 — Examples include national and international events (World Cups, Olympics), local competitions, multi-sport community events (e.g. Coast to Coast), activities such as pilates or snowboarding, movement-based festivals (e.g. Kapa Haka competitions).",
      "EN7 — Significance may relate to the event's context or concept, an incident during it, or a related issue."
