     "criteria": {
      "achieved": "Analyse group processes in physical activity.",
      "merit": "Analyse, in-depth, group processes in physical activity.",
      "excellence": "Analyse comprehensively group processes in physical activity."
     },
     "notes": [
      "EN2 — Analyse (Achieved) involves using ongoing reflection to explain group processes through experience in physical activity.",
      "EN2 — Analyse, in-depth (Merit) involves using ongoing reflection to explain group processes in relation to their nature and benefits, through experience in physical activity.",
      "EN2 — Analyse comprehensively (Excellence) involves using ongoing reflection to evaluate group processes in relation to their nature and benefits, through experience in physical activity.",
      "EN3 — Group processes are the behaviours and practices involved in a group's development and operation over time, e.g. member relationships, communication, roles, consensus and cohesion, conflict resolution, decision-making, negotiation, becoming interdependent.",
      "EN4 — Physical activity covers any individual activity done within a group, or any group activity, competitive or recreational, e.g. games, sport, dance, outdoor education, Te Ao Kori, aquatics."
     ],
     "clarifications": {
      "date": "December 2018",
      "points": [
       "Focus on how the group works during the activity, not the outcome of taking part: what happens, how and why people communicate, who led or held roles, how those roles arose and why. Responses must clearly name the group processes analysed.",
       "Students should take part in applying group processes during physical activity so they can use ongoing reflection.",
       "Analysis uses ongoing reflection to explain what the group process is, how and why it is experienced, and specific examples of it in practice.",
       "Comprehensive analysis: reflect over time to evaluate processes in terms of their nature and benefits — what worked well and what did not, and alternative or modified processes, behaviours or practices for the future — supported by evidence from the experience.",
       "Ongoing reflection applies at all levels and must happen over a period of time.",
       "Merit and Excellence: students must explain how the selected processes benefited the group's workings, which may include their characteristics or features as experienced."
      ]
     },
