   "slug": "physics",
   "discipline": "Level 2 Physics internals are judged on physics understanding shown in the student's own words, data and calculations: correct concepts, terms and equations applied to the situation, with higher grades coming from giving reasons and then linking concepts together. In the practical, the grade rests on the student's own measurements, graph and reasoning about how the data was made reliable. Describing the context well, copying researched text, length and presentation are never the criterion.",
