   "slug": "psychology",
   "discipline": "Level 2 Psychology is judged on how accurately and specifically a student explains behaviour, debates, theories and ethics using psychological concepts, and on the step from explaining (Achieved), to detailed explanation supported by named theories or studies from published works (Merit), to evaluating and justifying a judgement (Excellence). Retelling a famous study, generic statements and length are never the criterion; what matters is that each idea is explained, linked to the behaviour, field or issue in question, and backed by real published psychology.",
   "parallelHint": "a different behaviour (e.g. the bystander effect instead of aggression), a different psychological debate, a different field of practice, a different ethical issue or case, or a different research question and dependent variable",
   "privacyNote": "Research data may include participants' personal information; ethics evidence and reflections may describe classmates, whānau or the student's own experiences, so keep names and identifying details out of anything shared beyond the teacher.",
